#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Campground.Shared.Registry;

namespace Campground.Shared.Contracts
{
    /// <summary>
    /// An external service account (Steam, GOG, Epic, …) an admin linked, bound to the household profiles
    /// allowed to use it. Never carries the secret: secrets stay in the owning plugin's <see cref="Security.SecretBox"/>.
    /// </summary>
    internal sealed record ExternalAccount(
        string Id,
        string Service,
        string ExternalId,
        string DisplayName,
        IReadOnlyList<Guid> BoundUserIds,
        string OwnerPluginId,
        DateTime LinkedUtc);

    /// <summary>Arguments of <c>list</c>.</summary>
    internal sealed record AccountQuery(string? Service, Guid? UserId);

    /// <summary>
    /// <c>campground.accounts.v1</c> — profile-bound external accounts. The rule every plugin follows: a user
    /// (profile) may only use accounts bound to them, so nobody's cloud saves or purchases mix with another's.
    /// </summary>
    internal static class AccountsClient
    {
        internal const string ListOp = "list";

        /// <summary>Whether <paramref name="userId"/> may use <paramref name="account"/>.</summary>
        internal static bool CanUse(ExternalAccount account, Guid userId) => account.BoundUserIds.Contains(userId);

        /// <summary>Accounts visible to a user, from whichever plugin owns accounts. Empty when none does.</summary>
        internal static async Task<IReadOnlyList<ExternalAccount>> ListAsync(AccountQuery query, CancellationToken ct = default)
            => await Capabilities.TryInvokeAsync<List<ExternalAccount>>(CapabilityNames.Accounts, ListOp, query, ct: ct).ConfigureAwait(false)
               ?? new List<ExternalAccount>();

        /// <summary>For the provider (GameTent first).</summary>
        internal static void Provide(string pluginId, int minor, Func<AccountQuery, CancellationToken, Task<List<ExternalAccount>>> list)
            => Capabilities.Provide(CapabilityNames.Accounts, pluginId, minor, new CapabilityHost().On(ListOp, list).Build());

        /// <summary>
        /// Filters a full account list the way the contract requires. A query with no user gets nothing: it used to
        /// get every household's accounts and the user ids bound to them.
        /// </summary>
        internal static List<ExternalAccount> Filter(IEnumerable<ExternalAccount> all, AccountQuery q)
            => q.UserId is not { } userId
                ? new List<ExternalAccount>()
                : all.Where(a => (q.Service == null || string.Equals(a.Service, q.Service, StringComparison.OrdinalIgnoreCase))
                                 && CanUse(a, userId))
                     .ToList();
    }
}
